cat > bot.mjs <<'EOF'
// SMS send gate. Decides only; never sends. Stateless: every call uses only its arguments.
// Marketing texts follow 47 CFR 64.1200 (prior express written consent, STOP honored,
// 08:00 to before 21:00 recipient-local) and CTIA (consent first, opt-out honored).

const TRANSACTIONAL_MESSAGE_KINDS = new Set(["marketing", "transactional"]);

function hold(rule) {
  return { allowed: false, rule };
}

export async function checkSend({ user, message, now } = {}) {
  try {
    return decide(user, message, now);
  } catch {
    return hold("internal-error");
  }
}

function decide(user, message, now) {
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) return hold("invalid-time");
  if (!message || typeof message !== "object" || !TRANSACTIONAL_MESSAGE_KINDS.has(message.kind)) {
    return hold("invalid-message-kind");
  }
  if (typeof message.text !== "string" || message.text.trim() === "") return hold("empty-text");
  if (!user || typeof user !== "object") return hold("invalid-user");

  // Transactional: the customer asked for it or placed the order. Quiet hours and
  // marketing consent do not apply.
  if (message.kind === "transactional") return { allowed: true, rule: "" };

  // Marketing from here on.
  const sms = user.sms;
  if (!sms || typeof sms !== "object") return hold("no-consent");

  // An opt-out beats everything. Any recorded value counts, even one we cannot parse.
  const out = sms.optedOutAt;
  if (out !== null && out !== undefined) {
    return hold(typeof out === "string" && Number.isNaN(Date.parse(out)) ? "opt-out-unreadable" : "opted-out");
  }
  if (sms.optedIn !== true) return hold("no-consent");

  const zone = user.timeZone;
  if (typeof zone !== "string" || zone === "" || !gkZoneOk(zone)) return hold("no-valid-timezone");

  // US calling hours, applied to every recipient: 08:00 to before 21:00 local.
  if (!gkInWindow(now.getTime(), zone, "08:00", "21:00")) return hold("outside-calling-hours");

  return { allowed: true, rule: "" };
}
EOF
