await c("tokyo 21:00", { user: u("Asia/Tokyo"), message: m, now: D("2026-10-23T12:00:00Z") }, "outside-calling-hours");
await c("india 08:00", { user: u("Asia/Kolkata"), message: m, now: D("2026-10-23T02:30:00Z") }, "");
await c("india 07:59", { user: u("Asia/Kolkata"), message: m, now: D("2026-10-23T02:29:00Z") }, "outside-calling-hours");
const noon = D("2026-10-23T18:00:00Z");
await c("null tz", { user: u(null), message: m, now: noon }, "no-valid-timezone");
await c("bad tz", { user: u("Mars/Base"), message: m, now: noon }, "no-valid-timezone");
await c("not opted in", { user: u("America/Chicago", { optedIn: false }), message: m, now: noon }, "no-consent");
await c("opted out", { user: u("America/Chicago", { optedOutAt: "2026-10-01T00:00:00Z" }), message: m, now: noon }, "opted-out");
await c("opt-out garbage", { user: u("America/Chicago", { optedOutAt: "x" }), message: m, now: noon }, "opt-out-unreadable");
await c("txn night", { user: u("America/Chicago", { optedIn: false, optedOutAt: "2026-10-01T00:00:00Z" }), message: t, now: D("2026-10-23T08:00:00Z") }, "");
await c("txn no tz", { user: u(null), message: t, now: noon }, "");
await c("bad now", { user: u("America/Chicago"), message: m, now: new Date("x") }, "invalid-time");
await c("bad kind", { user: u("America/Chicago"), message: { kind: "x", text: "a" }, now: noon }, "invalid-message-kind");
await c("undefined", undefined, "invalid-time");
await c("null user", { user: null, message: m, now: noon }, "invalid-user");
await c("sms missing", { user: { id: "1", timeZone: "America/Chicago" }, message: m, now: noon }, "no-consent");
EOF
